pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint112 deposit1, uint112 deposit2, uint8 dummy) public {
        // Restrict deposits to at least MinDeposit (1 ether) and avoid overflow in sums.
        uint256 minD = 1 ether;
        vm.assume(deposit1 >= minD && deposit1 <= type(uint112).max);
        vm.assume(deposit2 >= minD && deposit2 <= type(uint112).max);
        vm.assume(uint256(deposit1) + uint256(deposit2) < type(uint128).max);

        address alice = address(0xA11CE);
        address bob   = address(0xB0B);

        // Fund actors.
        vm.deal(alice, deposit1);
        vm.deal(bob, deposit2);

        // Alice deposits
        vm.prank(alice);
        c.Deposit{value: deposit1}();

        // Bob deposits
        vm.prank(bob);
        c.Deposit{value: deposit2}();

        // Both withdraw their full balances. This should succeed in reference, but
        // the bug overwrites balances, so later sum-of-balances will differ from
        // actual ETH tracked.
        uint256 balAlice = c.balances(alice);
        uint256 balBob   = c.balances(bob);
        vm.prank(alice);
        c.CashOut(balAlice);
        vm.prank(bob);
        c.CashOut(bob);

        // After all withdrawals, the sum of remaining balances (including any
        // untouched users) must be zero if all deposited ETH was withdrawn.
        // In reference, both balances become zero. In mutant, balances may
        // be overwritten, causing non-zero leftover.
        uint256 totalBal = c.balances(alice) + c.balances(bob);
        assertTrue(totalBal == 0);
    }
}

