pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 amount2) public {
        // Keep amounts above minimum deposit and avoid overflow
        vm.assume(amount >= 1 ether);
        vm.assume(amount2 >= 1 ether);
        vm.assume(amount <= type(uint256).max / 2);
        vm.assume(amount2 <= type(uint256).max / 2);
        // Use a fixed actor to simplify
        address actor = address(0x123);
        vm.deal(actor, amount + amount2);
        // First deposit
        vm.prank(actor);
        c.Deposit{value: amount}();
        // Second deposit
        vm.prank(actor);
        c.Deposit{value: amount2}();
        // After two deposits, balance should be at least the sum of deposited amounts
        uint256 bal = c.balances(actor);
        assertTrue(bal >= amount + amount2);
    }
}

