pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address user) public {
        vm.assume(user != address(0) && user != address(this) && user != address(c));
        bound(amount1, 1 ether, type(uint256).max / 2);
        bound(amount2, 1 ether, type(uint256).max / 2);
        vm.assume(amount1 + amount2 >= amount1);
        uint256 totalDeposit = amount1 + amount2;

        vm.deal(user, totalDeposit);
        vm.startPrank(user);
        c.Deposit{value: amount1}();
        c.Deposit{value: amount2}();
        uint256 balBefore = c.balances(user);
        require(balBefore > 0, "Setup failed: balance must be > 0");
        vm.stopPrank();

        vm.deal(user, 0);
        vm.startPrank(user);
        c.CashOut(balBefore);
        uint256 balAfter = c.balances(user);
        vm.stopPrank();

        assertTrue(balAfter == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address user, uint depositAmount, uint cashoutAmount) public payable {
        require(depositAmount >= 1 ether);
        require(address(this).balance >= depositAmount);
        uint balanceBefore = c.balances(user);
        c.Deposit{value: depositAmount}();
        uint balanceAfterDeposit = c.balances(user);
        require(balanceAfterDeposit >= cashoutAmount);
        c.CashOut(cashoutAmount);
        uint balanceAfterCashout = c.balances(user);
        assert(balanceAfterCashout == balanceBefore + depositAmount - cashoutAmount);
    }
    receive() external payable {}
}

